typedef struct { double Y0, Y1; int N; double X[RACE_RAIL_OPEN_CORNERS], Z[RACE_RAIL_OPEN_CORNERS]; } T_RACE_RAIL_OPEN;
static T_RACE_RAIL_OPEN s_railOpen[RACE_MAX_RAIL_OPEN];
